import { readFileSync } from 'node:fs'

const file = process.argv[2]
const src = readFileSync(file, 'utf8')
const d = [...src.matchAll(/\sd="([^"]+)"/g)].map((m) => m[1])

let minX = Infinity,
  minY = Infinity,
  maxX = -Infinity,
  maxY = -Infinity

const point = (x, y) => {
  if (x < minX) minX = x
  if (x > maxX) maxX = x
  if (y < minY) minY = y
  if (y > maxY) maxY = y
}

const cubic = (x0, y0, x1, y1, x2, y2, x3, y3) => {
  const N = 64
  for (let i = 0; i <= N; i++) {
    const t = i / N
    const mt = 1 - t
    const a = mt * mt * mt,
      b = 3 * mt * mt * t,
      c = 3 * mt * t * t,
      e = t * t * t
    point(a * x0 + b * x1 + c * x2 + e * x3, a * y0 + b * y1 + c * y2 + e * y3)
  }
}

for (const path of d) {
  const tokens = path.match(/[a-zA-Z]|-?\d*\.?\d+(?:e[-+]?\d+)?/gi) ?? []
  let i = 0
  let cmd = ''
  let x = 0,
    y = 0,
    sx = 0,
    sy = 0
  let px = 0,
    py = 0 // previous control for S
  const num = () => parseFloat(tokens[i++])
  while (i < tokens.length) {
    if (/[a-zA-Z]/.test(tokens[i])) cmd = tokens[i++]
    const rel = cmd === cmd.toLowerCase()
    const C = cmd.toUpperCase()
    if (C === 'M') {
      x = rel ? x + num() : num()
      y = rel ? y + num() : num()
      sx = x
      sy = y
      point(x, y)
      cmd = rel ? 'l' : 'L'
    } else if (C === 'L') {
      x = rel ? x + num() : num()
      y = rel ? y + num() : num()
      point(x, y)
    } else if (C === 'H') {
      x = rel ? x + num() : num()
      point(x, y)
    } else if (C === 'V') {
      y = rel ? y + num() : num()
      point(x, y)
    } else if (C === 'C') {
      const x1 = rel ? x + num() : num(),
        y1 = rel ? y + num() : num()
      const x2 = rel ? x + num() : num(),
        y2 = rel ? y + num() : num()
      const x3 = rel ? x + num() : num(),
        y3 = rel ? y + num() : num()
      cubic(x, y, x1, y1, x2, y2, x3, y3)
      px = x2
      py = y2
      x = x3
      y = y3
    } else if (C === 'S') {
      const x1 = 2 * x - px,
        y1 = 2 * y - py
      const x2 = rel ? x + num() : num(),
        y2 = rel ? y + num() : num()
      const x3 = rel ? x + num() : num(),
        y3 = rel ? y + num() : num()
      cubic(x, y, x1, y1, x2, y2, x3, y3)
      px = x2
      py = y2
      x = x3
      y = y3
    } else if (C === 'Z') {
      x = sx
      y = sy
    } else {
      throw new Error(`unhandled command ${cmd}`)
    }
  }
}

console.log(
  JSON.stringify(
    { minX, minY, maxX, maxY, w: maxX - minX, h: maxY - minY },
    null,
    2,
  ),
)

