  const title = options.title ?? "Instructure color tokens";
  const columns = Math.max(1, options.columns ?? 6);
  const width = MARGIN * 2 + columns * CELL_W + (columns - 1) * GAP_X;
  const groups = group(swatches);

  const body: string[] = [];
  let y = MARGIN + TITLE_H;

  for (const g of groups) {
    body.push(`<text x="${MARGIN}" y="${y}" class="group">${esc(g.name)}</text>`);
    const top = y + GROUP_HEAD_H;
    const rows = Math.ceil(g.items.length / columns);
    g.items.forEach(({ label, swatch }, i) => {
      const x = MARGIN + (i % columns) * (CELL_W + GAP_X);
      const cy = top + Math.floor(i / columns) * (CELL_H + GAP_Y);
      body.push(
        `<g transform="translate(${x},${cy})">`,
        `<rect width="${CELL_W}" height="${SWATCH_H}" rx="6" fill="${esc(swatch.hex)}" class="chip"/>`,
        `<text x="0" y="${SWATCH_H + 16}" class="leaf">${esc(label)}</text>`,
        `<text x="0" y="${SWATCH_H + 29}" class="hex">${esc(swatch.hex.toUpperCase())}</text>`,
        `</g>`,
      );
    });
    y = top + rows * CELL_H + (rows - 1) * GAP_Y + GROUP_GAP;
  }

  const height = y + MARGIN - GROUP_GAP;

  return [
    `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}" font-family="system-ui, sans-serif">`,
    `<style>`,
    `.bg { fill: #ffffff; }`,
    `.title { fill: #111827; font-size: 20px; font-weight: 700; }`,
    `.group { fill: #374151; font-size: 14px; font-weight: 600; }`,
    `.chip { stroke: rgba(0,0,0,0.15); stroke-width: 1; }`,
    `.leaf { fill: #374151; font-size: 11px; }`,
    `.hex { fill: #9ca3af; font-size: 10px; font-family: ui-monospace, monospace; }`,
    `</style>`,
    `<rect class="bg" width="${width}" height="${height}"/>`,
    `<text x="${MARGIN}" y="${MARGIN + 20}" class="title">${esc(title)}</text>`,
    ...body,
    `</svg>`,
    ``,
  ].join("\n");
}"},{"rank":2,"score":61.6283,"file_path":"formats/icon-font/src/build.ts","start_line":85,"end_line":129,"focus_line":116,"snippet_start_line":85,"snippet_end_line":129,"symbol_start_line":85,"symbol_end_line":129,"language":"TypeScript","kind":"function","symbol_id":"gh/thedannywahl/pantoken:TypeScript:formats/icon-font/src/build.ts:function:buildIconFont","symbol_name":"buildIconFont","qualified_name":"buildIconFont","signature":"async function buildIconFont(options: BuildIconFontOptions = {}): Promise<IconFontResult>","signals":["path","body","symbol-name","symbol-usage","complete-symbol"],"snippet":"export async function buildIconFont(options: BuildIconFontOptions = {}): Promise<IconFontResult> {
  const fontName = options.fontName ?? "PanTokens";
  const svgs = getIconSvgs(byTheme(options.theme ?? "rebrand"));
  const names = (options.icons?.length ? options.icons : [...svgs.keys()])
    .filter((n) => svgs.has(n))
    .sort();

  const stream = new SVGIcons2SVGFontStream({
    fontName,
    fontHeight: 1000,
    normalize: true,
  });
  let svgFont = "";
  stream.on("data", (chunk: Buffer) => {
    svgFont += chunk.toString();
  });
  const done = new Promise<void>((resolve, reject) => {
    stream.on("end", resolve);
    stream.on("error", reject);
  });

  const codepoints: Record<string, string> = {};
  let codepoint = 0xe000;
  for (const name of names) {
    const svg = svgs.get(name);
    if (!svg) continue;
    const { d, width, height } = svgToGlyphPath(svg);
    if (!d) continue;
    const code = codepoint++;
    codepoints[name] = code.toString(16);
    const glyph = Readable.from([
      `<svg viewBox="0 0 ${width} ${height}"><path d="${d}"/></svg>`,
    ]) as Readable & { metadata: { unicode: string[]; name: string } };
    glyph.metadata = { unicode: [String.fromCodePoint(code)], name };
    stream.write(glyph);
  }
  stream.end();
  await done;

  const ttf = new Uint8Array(
    svg2ttf(svgFont, { description: "Instructure icons (pantoken)" }).buffer,
  );
  const woff2 = new Uint8Array(ttf2woff2(ttf));
  return { ttf, woff2, css: css(fontName, codepoints), codepoints };
}"},{"rank":3,"score":61.6283,"file_path":"formats/icon-font/src/outline.ts","start_line":11,"end_line":15,"focus_line":13,"snippet_start_line":11,"snippet_end_line":15,"language":"TypeScript","signals":["path","body","symbol-usage"],"snippet":"import svgpath from "svgpath";

